     */
    public function unsetNsec3(string $domain): array
    {
        /** @var UnsetNsec3Result $result Validated against DnssecSpec::UNSET_NSEC3. */
        $result = ($this->run)(DnssecSpec::UNSET_NSEC3, ['domain' => $domain]);

        return $result;
    }
